  }
}

// Phase 3: Continue free generation up to 72% of budget, watching for second "<<"
var phase3Limit: nat := (maxSteps * 72) / 100;
if phase3Limit < phase1Limit { phase3Limit := phase1Limit; }

while steps < phase3Limit && !insideConstrainedOut && !hasCompletedSpan
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase3Limit - steps
{
  var next3 := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next3 == eosToken {
    break;
  }
  generated := generated + [next3];
  if RenderedEndsWith(generated, "<<") {
    var eg3, ei3, ec3 := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg3;
    insideConstrainedOut := ei3;
    currentConstrainedOut := ec3;
  }
}

// Phase 4a: Build minInnerTokens for the second span entry
var tokenBuilt4: nat := 0;
while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && tokenBuilt4 < minInnerTokens
  invariant 0 <= tokenBuilt4 <= minInnerTokens
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases (maxSteps - steps) + (minInnerTokens - tokenBuilt4)
{
  var constrainedPrompt4 := prompt + generated[..|generated| - |currentConstrainedOut|];
  var next4 := helpers.ConstrainedStep(lm, parser, constrainedPrompt4, currentConstrainedOut, eosToken);
  steps := steps + 1;
  tokenBuilt4 := tokenBuilt4 + 1;
  if next4 == eosToken {
    break;
  }
  var ag4, ai4, ac4 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next4);
  generated := ag4;
  insideConstrainedOut := ai4;
  currentConstrainedOut := ac4;
}

// Phase 4b: Close second span with generous budget
if insideConstrainedOut && !hasCompletedSpan && steps < maxSteps {
  var remaining4b := maxSteps - steps;
  var spanBudget4b: nat := 300;
  if spanBudget4b > remaining4b { spanBudget4b := remaining4b; }
  if spanBudget4b > 0 {
    var wg4b, wi4b, wc4b := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, spanBudget4b);
    generated := wg4b;
    insideConstrainedOut := wi4b;
    currentConstrainedOut := wc4b;
    steps := steps + spanBudget4b;
    if !insideConstrainedOut { hasCompletedSpan := true; }
  }
}

// Phase 5: Force-open a span if no span has been completed yet
if !insideConstrainedOut && !hasCompletedSpan && steps + 2 <= maxSteps {
  var fg, fi, fc := helpers.OpenConstrainedSpan(lm, generated);
  generated := fg;
  insideConstrainedOut := fi;
  currentConstrainedOut := fc;
  steps := steps + 1;

  var tokenBuilt5: nat := 0;
  while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && tokenBuilt5 < minInnerTokens
    invariant 0 <= tokenBuilt5 <= minInnerTokens
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases (maxSteps - steps) + (minInnerTokens - tokenBuilt5)
  {
    var constrainedPrompt5 := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next5 := helpers.ConstrainedStep(lm, parser, constrainedPrompt5, currentConstrainedOut, eosToken);
    steps := steps + 1;
    tokenBuilt5 := tokenBuilt5 + 1;
    if next5 == eosToken {
      break;
    }
    var ag5, ai5, ac5 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next5);
    generated := ag5;
    insideConstrainedOut := ai5;
    currentConstrainedOut := ac5;
  }

  if insideConstrainedOut && steps < maxSteps {
    var remaining5 := maxSteps - steps;
    var budget5: nat := 200;
    if budget5 > remaining5 { budget5 := remaining5; }
    if budget5 > 0 {
      var wg5, wi5, wc5 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget5);
      generated := wg5;
      insideConstrainedOut := wi5;
      currentConstrainedOut := wc5;
      steps := steps + budget5;
    }
  }
}

// Final safety: consume all remaining budget to guarantee span closure
if insideConstrainedOut && steps < maxSteps {
  var finalBudget := maxSteps - steps;
  if finalBudget > 0 {
    var wgf, wif, wcf := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, finalBudget);
    generated := wgf;
    insideConstrainedOut := wif;
    currentConstrainedOut := wcf;
    steps := steps + finalBudget;
  }
}

cost := steps;
